mapper.select:
select
ACT_HI_PROCINST.PROC_INST_ID_ as processId, ACT_HI_PROCINST.NAME_ as processName, ACT_HI_PROCINST.REV_ as processVersion, ACT_HI_PROCINST.BUSINESS_KEY_ as businessKey, DATE_FORMAT(ACT_HI_PROCINST.START_TIME_, '%Y-%m-%d %H:%i:%s') as startTime, ACT_HI_PROCINST.STATE_ as processState,
ACT_RU_TASK.ID_ as taskId, ACT_RU_TASK.STATE_ as taskState, ACT_RU_TASK.NAME_ as taskName, ACT_RU_TASK.ASSIGNEE_ as assignee, DATE_FORMAT(ACT_RU_TASK.CREATE_TIME_, '%Y-%m-%d %H:%i:%s') as createTime, DATE_FORMAT(ACT_RU_TASK.CLAIM_TIME_, '%Y-%m-%d %H:%i:%s') as claimTime from ACT_RU_TASK LEFT JOIN ACT_HI_PROCINST ON ACT_RU_TASK.PROC_INST_ID_ = ACT_HI_PROCINST.PROC_INST_ID_ where ACT_RU_TASK.ASSIGNEE_ = #{userId} and ACT_RU_TASK.STATE_ NOT IN ('completed', 'claim') order by ACT_RU_TASK.CREATE_TIME_ desc;
